import{_ as a,c as e,o as r,ae as i}from"./chunks/framework.Bi6zybwU.js";const w=JSON.parse('{"title":"How to Create Dynamic Charts with Ninja Charts","description":"How to Create Dynamic Charts with Ninja Charts","frontmatter":{"title":"How to Create Dynamic Charts with Ninja Charts","description":"How to Create Dynamic Charts with Ninja Charts"},"headers":[],"relativePath":"guide/ninja-charts/how-to-create-dynamic-charts-with-ninja-charts.md","filePath":"guide/ninja-charts/how-to-create-dynamic-charts-with-ninja-charts.md"}'),n={name:"guide/ninja-charts/how-to-create-dynamic-charts-with-ninja-charts.md"};function o(s,t,h,l,c,d){return r(),e("div",null,[...t[0]||(t[0]=[i('<h1 id="how-to-create-dynamic-charts-with-ninja-charts" tabindex="-1">How to Create Dynamic Charts with Ninja Charts <a class="header-anchor" href="#how-to-create-dynamic-charts-with-ninja-charts" aria-label="Permalink to &quot;How to Create Dynamic Charts with Ninja Charts&quot;">​</a></h1><p>Once you install and activate Ninja Charts, this plugin is ready to create any type of chart you want! As a free WordPress chart plugin, Ninja Charts makes the process of creating online charts very easy. <img src="https://ninjatables.com/wp-content/uploads/2023/10/Create-a-chart-01-scaled.webp" alt=""> Chart renderer in Ninja Charts:</p><ul><li>Charts Js</li><li>Google Charts Chart options in Ninja Charts (Charts from both renderers):</li><li>Line Chart</li><li>Pie Chart</li><li>Bar Chart</li><li>Horizontal Bar</li><li>Bubble Chart</li><li>Doughnut Chart</li><li>Scatter Chart</li><li>Area Chart</li><li>Combo Chart</li><li>Radar Chart</li><li>Polar Chart</li></ul><h2 id="creating-wordpress-charts-with-ninja-charts" tabindex="-1">Creating WordPress Charts with Ninja Charts <a class="header-anchor" href="#creating-wordpress-charts-with-ninja-charts" aria-label="Permalink to &quot;Creating WordPress Charts with Ninja Charts&quot;">​</a></h2><p>First of all, go to the Ninja Charts dashboard and click the “Add New” button. <img src="https://ninjatables.com/wp-content/uploads/2023/10/Charts-%E2%80%B9-North-%E2%80%94-WordPress-06-03-2025_11_33_AM-scaled.webp" alt=""></p><ul><li>Enter the chart name.</li><li>Choose a <strong>Chart Renderer</strong>. Choose either Google Charts or Chart Js.</li><li>After choosing Chart Js here, you’ll see multiple chart types. Let’s pick one.</li><li>We’ve selected the Horizontal Bar chart for demonstration and clicked Next. <img src="https://ninjatables.com/wp-content/uploads/2023/10/Choose-chart-type-02-scaled.webp" alt=""></li><li>After this, you have to select the <strong>Data Source</strong> from the Source option.</li><li>Manual Input</li><li>Ninja Tables</li><li>Fluent Forms <img src="https://ninjatables.com/wp-content/uploads/2023/10/Data-Source-03-scaled.webp" alt=""> Here, we’ve selected <strong>Ninja Tables</strong> as the data source as an example.</li><li>Now, select the table you want to turn into a chart from the dropdown. <img src="https://ninjatables.com/wp-content/uploads/2023/10/Data-04-scaled.webp" alt=""></li><li>Hit **Next **and now you’re in the <strong>Data Range</strong> tab where you can choose what table entries you want in your chart. <img src="https://ninjatables.com/wp-content/uploads/2023/10/Column-in-data-source-05-scaled.webp" alt=""></li><li>You can customize it all you want in the <strong>Formatting &amp; Preview</strong> tab. So, here&#39;s the Horizontal Bar chart by Ninja Charts made with the chosen data table in Ninja Tables in the <strong>Formatting &amp; Preview</strong> tab. <img src="https://ninjatables.com/wp-content/uploads/2023/10/Formatting-Review-06-scaled.webp" alt=""> Now hit <strong>Save</strong> and get the shortcode from the next tab. <img src="https://ninjatables.com/wp-content/uploads/2023/10/Finish-07-scaled.webp" alt=""> Copy the auto-generated shortcode and paste it anywhere on your website. This is how you can create different charts using Ninja Charts.</li></ul>',6)])])}const C=a(n,[["render",o]]);export{w as __pageData,C as default};
